import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import {
  Archive,
  ArrowUpRight,
  Bookmark,
  BookOpen,
  Check,
  ChevronDown,
  CircleUserRound,
  Clock3,
  Folder,
  Grid2X2,
  Heart,
  LayoutList,
  Menu,
  MoreHorizontal,
  Pencil,
  Plus,
  Search,
  Sparkles,
  Star,
  Trash2,
  X,
} from 'lucide-react';
import './styles.css';

const SEED_BOOKMARKS = [
  {
    id: 1,
