.view-toggle button { width: 34px; height: 31px; display: grid; place-items: center; border: 0; border-right: 1px solid #d6d3ca; background: transparent; color: #94958f; cursor: pointer; }.view-toggle button:last-child { border: 0; }.view-toggle button.active { background: #fffdfa; color: var(--teal); }

