.bookmark-card:hover { transform: translateY(-3px); box-shadow: 0 12px 28px rgba(48,49,43,.08); border-color: #cfcbc0; }
.card-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 24px; }
.site-icon { width: 42px; height: 42px; display: grid; place-items: center; background: color-mix(in srgb, var(--site-color) 13%, white); border: 1px solid color-mix(in srgb, var(--site-color) 27%, white); color: var(--site-color); border-radius: 9px; text-decoration: none; font-size: 12px; font-weight: 600; letter-spacing: -.02em; }
.card-actions { display: flex; align-items: center; gap: 3px; }.card-actions button { border: 0; background: transparent; display: grid; place-items: center; color: #9a9b96; cursor: pointer; padding: 5px; border-radius: 5px; }.card-actions button:hover { background: #eeece5; color: #686a65; }.card-actions .favorite-button.selected { color: #c36250; }
.menu-wrap { position: relative; }.context-menu { position: absolute; z-index: 5; top: 29px; right: 0; width: 116px; padding: 5px; border: 1px solid #d8d5cc; border-radius: 7px; background: #fffefa; box-shadow: 0 8px 24px rgba(40,40,35,.13); }.context-menu button { width: 100%; display: flex; grid-template-columns: none; flex-direction: row; justify-content: flex-start; gap: 8px; color: #555852; padding: 7px; font-size: 11px; }.context-menu button.danger { color: #a64f43; }
.card-copy { flex: 1; }.title-link { display: flex; align-items: center; gap: 5px; width: fit-content; color: var(--ink); text-decoration: none; }.title-link svg { opacity: 0; transform: translate(-3px, 3px); transition: .2s ease; color: var(--teal); }.title-link:hover svg { opacity: 1; transform: none; }
.card-copy h3 { margin-bottom: 3px; font: 400 21px/1.2 'DM Serif Display', serif; letter-spacing: -.2px; }
.domain { color: #989993; font-size: 10px; }.card-copy p { margin: 14px 0 20px; color: #696b66; font-size: 12px; line-height: 1.55; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.card-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; padding-top: 15px; border-top: 1px solid #e6e2d9; }
.tags { display: flex; gap: 5px; flex-wrap: wrap; }.tags button { border: 0; background: #eceae3; border-radius: 4px; padding: 4px 7px; color: #73756f; font-size: 9px; cursor: pointer; }.tags button:hover { color: var(--teal); }
.date { display: flex; align-items: center; gap: 4px; color: #9a9b96; font-size: 9px; white-space: nowrap; }
.bookmark-grid.list-view { grid-template-columns: 1fr; }.bookmark-card.list { display: grid; grid-template-columns: 54px minmax(250px, 1fr) auto; align-items: center; min-height: 116px; padding: 18px 20px; }.bookmark-card.list .card-top { margin: 0; display: block; }.bookmark-card.list .card-actions { position: absolute; right: 20px; top: 16px; }.bookmark-card.list { position: relative; }.bookmark-card.list .card-copy { padding-right: 150px; }.bookmark-card.list .card-copy p { margin: 7px 0 0; -webkit-line-clamp: 1; }.bookmark-card.list .card-bottom { min-width: 180px; border: 0; padding: 25px 60px 0 0; align-items: center; }

.modal-backdrop { position: fixed; inset: 0; z-index: 100; display: grid; place-items: center; background: rgba(30,35,32,.52); backdrop-filter: blur(5px); padding: 20px; animation: fade-in .15s ease; }
.modal { width: min(570px, 100%); max-height: calc(100vh - 40px); overflow-y: auto; background: #faf8f2; border: 1px solid #d9d5ca; border-radius: 13px; padding: 28px; box-shadow: 0 24px 60px rgba(25,30,27,.28); animation: rise .2s ease; }
.modal-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 25px; }.modal-header h2 { font: 400 31px 'DM Serif Display', serif; margin: 0; }.modal label { display: block; margin-bottom: 16px; color: #5f615c; font-size: 11px; font-weight: 600; }.modal input, .modal textarea, .modal select { display: block; width: 100%; margin-top: 7px; border: 1px solid #d7d4cb; border-radius: 7px; background: #fffefa; padding: 11px 12px; color: var(--ink); outline: none; font-weight: 400; resize: vertical; }.modal input:focus, .modal textarea:focus, .modal select:focus { border-color: #8eaaa4; box-shadow: 0 0 0 3px rgba(29,111,106,.08); }.form-row { display: grid; grid-template-columns: 1fr 1.2fr; gap: 14px; }.form-error { color: #ac493d; font-size: 11px; }.modal-footer { display: flex; justify-content: flex-end; gap: 9px; margin-top: 25px; padding-top: 20px; border-top: 1px solid var(--line); }
.empty-state { margin: 75px auto 0; text-align: center; max-width: 390px; }.empty-icon { width: 60px; height: 60px; display: grid; place-items: center; margin: 0 auto 17px; background: #e3ebe7; color: var(--teal); border-radius: 50% 50% 45% 55%; }.empty-state h2 { font: 400 28px 'DM Serif Display', serif; margin-bottom: 7px; }.empty-state p { color: var(--muted); font-size: 13px; line-height: 1.5; margin-bottom: 21px; }
.toast { position: fixed; z-index: 200; bottom: 26px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; background: #252d29; color: white; border-radius: 7px; padding: 11px 16px; font-size: 12px; box-shadow: 0 10px 30px rgba(20,25,22,.2); animation: rise .2s ease; }.toast svg { color: #8fc9af; }
.floating-add { display: none; }
.sidebar-scrim { display: none; }

@keyframes fade-in { from { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(8px); } }

@media (max-width: 1100px) {
  .bookmark-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .bookmark-card.list { grid-template-columns: 54px 1fr; }.bookmark-card.list .card-bottom { display: none; }.bookmark-card.list .card-copy { padding-right: 40px; }
}

@media (max-width: 760px) {
  .sidebar { transform: translateX(-100%); transition: transform .25s ease; box-shadow: 15px 0 40px rgba(30,35,32,.18); }.sidebar.open { transform: translateX(0); }.sidebar-scrim { display: block; position: fixed; inset: 0; z-index: 19; background: rgba(30,35,32,.35); opacity: 0; pointer-events: none; transition: .25s; }.sidebar-scrim.visible { opacity: 1; pointer-events: auto; }
  .content { margin-left: 0; }.topbar { height: 70px; padding: 0 17px; gap: 8px; }.menu-button, .profile-mobile, .mobile-close { display: grid !important; }.profile-mobile { flex-shrink: 0; }.search-wrap { flex: 1; width: auto; }.search-wrap kbd { display: none; }.search-wrap input { height: 39px; padding-right: 36px; }.search-wrap button { right: 10px; }.add-top { display: none; }
  .content-inner { padding: 36px 18px 90px; }.page-intro { align-items: flex-start; margin-bottom: 30px; }.stats { display: none; }.filter-row { align-items: flex-start; }.tag-filters { flex-wrap: nowrap; overflow-x: auto; margin-right: -18px; padding-right: 18px; scrollbar-width: none; }.sort-control { display: none; }.view-controls { margin-left: auto; }
  .bookmark-grid { grid-template-columns: 1fr; }.bookmark-card { min-height: 270px; }.bookmark-card.list { grid-template-columns: 52px 1fr; }.bookmark-card.list .card-copy p { display: none; }
  .floating-add { position: fixed; z-index: 12; right: 20px; bottom: 20px; display: grid; place-items: center; width: 52px; height: 52px; border: 0; border-radius: 50%; background: var(--teal); color: white; box-shadow: 0 8px 22px rgba(29,111,106,.3); }.form-row { grid-template-columns: 1fr; gap: 0; }.modal { padding: 22px; }
}

@media (max-width: 420px) {
  .bookmark-card.list { display: flex; min-height: 240px; }.bookmark-card.list .card-top { display: flex; }.bookmark-card.list .card-actions { position: static; }.bookmark-card.list .card-copy { padding: 0; }.bookmark-card.list .card-copy p { display: -webkit-box; }.bookmark-card.list .card-bottom { display: flex; padding: 15px 0 0; min-width: 0; border-top: 1px solid #e6e2d9; }
}

