          </button>
          <button className={currentView === 'Favorites' ? 'active' : ''} onClick={() => select('Favorites')}>
            <span><Star size={18} />Favorites</span><small>{itemCount('Favorites')}</small>
          </button>
        </nav>
        <div className="nav-section">
